parameters.jsCode:
// Test claim used when the workflow is run by hand from the editor.
// The orchestrator sends the same shape through "When called by orchestrator".
//
// The workflow never asks for a location: it comes with the claim. Real claims get the pin from
// the map on the claim form. To test another spot here, replace incident_lat / incident_lon:
// in Google Maps or openstreetmap.org, right-click the spot and copy its coordinates.
// Delete both lines to test with the typed address only (less precise).
return [{
  json: {
    claim_id: 'CLM-TEST-0001',
    incident_datetime: '2026-03-14T18:40:00', // local time at the incident location
    incident_lat: 36.8004, // map pin: traffic light on Avenue Habib Bourguiba, downtown Tunis
    incident_lon: 10.1866,
    incident_location: 'Avenue Habib Bourguiba, Tunis, Tunisia',
    description:
      'I was stopped at the traffic light on Avenue Habib Bourguiba when the car behind me ' +
      'hit the back of my car. It was raining heavily and already dark.',
    invoice: {
      line_items: [
        { part: 'rear_bumper' },
        { part: 'taillight_left' },
        { part: 'radiator' },
      ],
    },
  },
}];

// Validates the input contract and derives the fields the later nodes need.
// Accepts the claim at the top level, or wrapped as { claim } the way the intake form sends it.
const c = $input.first().json.claim || $input.first().json;

// Optional map pin from the claim form. When present it replaces the typed address,
// which removes the "wrong street with the same name" geocoding problem.
const pinLat = Number.parseFloat(c.incident_lat);
const pinLon = Number.parseFloat(c.incident_lon);
const hasPin = Number.isFinite(pinLat) && Number.isFinite(pinLon)
  && Math.abs(pinLat) <= 90 && Math.abs(pinLon) <= 180;

const required = ['claim_id', 'incident_datetime', 'description'];
const missing = required.filter((k) => !c[k]);
if (!c.incident_location && !hasPin) missing.push('incident_location (or incident_lat + incident_lon)');
if (missing.length) {
  throw new Error(`Incident Plausibility: missing input fields: ${missing.join(', ')}`);
}

// incident_datetime is local time at the incident location, e.g. "2026-03-14T18:40:00".
const dt = String(c.incident_datetime);
const date = dt.slice(0, 10);
const hour = Number(dt.slice(11, 13) || 12);
const minute = Number(dt.slice(14, 16) || 0);
const daysAgo = Math.floor((Date.now() - new Date(`${date}T00:00:00Z`).getTime()) / 86400000);
if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(daysAgo)) {
  throw new Error(`Incident Plausibility: invalid incident_datetime "${dt}"`);
}
if (daysAgo < 0) throw new Error('Incident Plausibility: incident_datetime is in the future');

// The invoice may sit inside the claim or next to it ({ claim, invoice }).
const invoice = c.invoice || $input.first().json.invoice || {};

const NOMINATIM = 'https://nominatim.openstreetmap.org';
const search = (q) => `${NOMINATIM}/search?format=jsonv2&limit=1&q=${encodeURIComponent(q)}`;

return [{
  json: {
    claim_id: c.claim_id,
    incident_date: date,
    incident_hour: hour,
    incident_minutes: hour * 60 + minute,
    days_ago: daysAgo,
    incident_location: c.incident_location ? String(c.incident_location) : null,
    // Street, city, postal code and country as typed in the claim form, when available.
    incident_address: c.incident_address && typeof c.incident_address === 'object' ? c.incident_address : null,
    has_pin: hasPin,
    pin_lat: hasPin ? pinLat : null,
    pin_lon: hasPin ? pinLon : null,
    // With a pin, reverse geocoding only fetches a readable address for the evidence text.
    incident_geocode_url: hasPin
      ? `${NOMINATIM}/reverse?format=jsonv2&zoom=17&lat=${pinLat}&lon=${pinLon}`
      : search(String(c.incident_location)),
    // Cap the length so a huge description cannot blow up the prompt cost.
    description: String(c.description).slice(0, 4000),
    invoice_parts: (invoice.line_items || []).map((li) => li.part).filter(Boolean),
  },
}];

// LLM provider layer. The prompts are written once (OpenAI chat format); this turns them
// into requests any OpenAI-compatible provider accepts, and checks the answers.
// Pick the provider in the "LLM settings" node of the workflow.
const LLM = (() => {
  // Free model names and limits change: check your provider's console if a call fails.
  // structured: 'json_schema' = strict schema enforced by the provider
  //             'json_object' = JSON mode; the schema goes into the prompt
  //             'prompt'      = no JSON mode; the schema goes into the prompt
  // supportsN: provider can return several answers in one call (n = 3)
  // callIntervalMs: pause between LLM calls. Free tiers limit tokens per minute; one claim uses
  //   about 10,000 tokens (1 extraction + 3 reconstruction calls), so calls must be spread out.
  // extra: request fields added when the model name contains the key.
  const PROVIDERS = {
    groq: {
      url: 'https://api.groq.com/openai/v1/chat/completions',
      // openai/gpt-oss-120b: confirmed available on Groq's free tier during setup.
      models: { extraction: 'openai/gpt-oss-120b', reconstruction: 'openai/gpt-oss-120b' },
      structured: 'json_object', supportsN: false, keyHint: 'console.groq.com → API Keys (free)',
      callIntervalMs: 25000,
      // gpt-oss "thinks" before answering; low effort keeps it fast and within the token limit.
      extra: { 'gpt-oss': { reasoning_effort: 'low' } },
    },
    gemini: {
      url: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
      models: { extraction: 'gemini-2.5-flash-lite', reconstruction: 'gemini-2.5-flash' },
      structured: 'prompt', supportsN: false, keyHint: 'aistudio.google.com → Get API key (free)',
      callIntervalMs: 7000,
    },
    openrouter: {
      url: 'https://openrouter.ai/api/v1/chat/completions',
      models: { extraction: 'meta-llama/llama-3.3-70b-instruct:free', reconstruction: 'meta-llama/llama-3.3-70b-instruct:free' },
      structured: 'prompt', supportsN: false, keyHint: 'openrouter.ai → Keys (free models end in :free)',
      callIntervalMs: 4000,
    },
    ollama: {
      // Runs on your own computer: no key, no cost. From inside Docker, the host is host.docker.internal.
      url: 'http://host.docker.internal:11434/v1/chat/completions',
      // claimshield-recon = the fine-tuned Qwen2.5-3B (dev/finetune). qwen2.5:3b = the same model
      // before fine-tuning, for comparisons (ollama pull qwen2.5:3b).
      models: { extraction: 'qwen2.5:3b', reconstruction: 'claimshield-recon' },
      structured: 'json_object', supportsN: false, keyHint: 'no key needed (any value works)',
      callIntervalMs: 0,
    },
    openai: {
      url: 'https://api.openai.com/v1/chat/completions',
      models: { extraction: 'gpt-4o-mini', reconstruction: 'gpt-4o' },
      structured: 'json_schema', supportsN: true, keyHint: 'platform.openai.com (paid)',
      callIntervalMs: 0,
    },
  };

  const schemaInstruction = (schema) =>
    '\n\nOUTPUT FORMAT: reply with ONE JSON object and nothing else (no prose, no code fences). '
    + 'It must match this JSON schema exactly; every key is required, and enum fields must use one of the listed values:\n'
    + JSON.stringify(schema);

  // OpenAI-style request body -> list of request bodies for the chosen provider.
  // Self-consistency (n = 3) becomes 3 separate calls when the provider has no "n".
  // provider.samples (set in "LLM settings") can lower the number of reconstruction samples.
  const toRequests = (body, provider, role) => {
    const b = JSON.parse(JSON.stringify(body));
    b.model = provider.models[role];
    b.stream = false; // one complete answer, not a stream of chunks
    for (const [match, fields] of Object.entries(provider.extra || {})) {
      if (b.model.includes(match)) Object.assign(b, fields);
    }
    const samples = b.n > 1 && provider.samples ? provider.samples : b.n || 1;
    delete b.n;
    const rf = b.response_format;
    if (rf && rf.type === 'json_schema' && provider.structured !== 'json_schema') {
      b.messages[0].content += schemaInstruction(rf.json_schema.schema);
      if (provider.structured === 'json_object') b.response_format = { type: 'json_object' };
      else delete b.response_format;
    }
    if (samples > 1 && provider.supportsN) return [{ ...b, n: samples }];
    return Array.from({ length: samples }, () => b);
  };

  // Text of the first answer in a chat-completions response. When the LLM node passed on
  // something else (a provider error, a text response), say what it was instead of crashing.
  const contentOf = (json) => {
    let j = json || {};
    // Streamed answer ("stream": true): text lines "data: {chunk}". Join the chunks' content.
    if (!j.choices && typeof j.data === 'string' && j.data.trimStart().startsWith('data:')) {
      const text = j.data.split('\n')
        .map((line) => line.trim())
        .filter((line) => line.startsWith('data:') && !line.includes('[DONE]'))
        .map((line) => { try { return JSON.parse(line.slice(5)); } catch (e) { return null; } })
        .filter(Boolean)
        .map((chunk) => (chunk.choices && chunk.choices[0] && chunk.choices[0].delta && chunk.choices[0].delta.content) || '')
        .join('');
      j = { choices: [{ message: { content: text } }] };
    }
    // HTTP node set to return text: the JSON arrives as a string in "data".
    if (!j.choices && typeof j.data === 'string') { try { j = JSON.parse(j.data); } catch (e) { /* below */ } }
    const content = j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content;
    if (typeof content === 'string') return content;
    const err = j.error && (j.error.message || j.error.description || j.error);
    const hint = err
      ? `The provider returned an error: ${typeof err === 'string' ? err : JSON.stringify(err)}`
      : `Unexpected response: ${JSON.stringify(j).slice(0, 300)}`;
    throw new Error(`${hint}. Check the LLM node's credential (Header Auth, value "Bearer <key>"), URL and model. `
      + 'In the LLM node, Settings → On Error must be "Stop Workflow" and Response Format "JSON".');
  };

  // Tolerates code fences or text around the JSON, which some free models add.
  const parse = (content) => {
    const text = String(content || '').replace(/```(?:json)?/gi, '');
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start < 0 || end <= start) {
      throw new Error(`The model answered with text instead of JSON: "${text.trim().slice(0, 160)}". `
        + 'This usually means the LLM node did not send the request built by the previous node. '
        + 'In the LLM node, the body must be JSON with the expression {{ JSON.stringify($json.body) }} '
        + 'and the URL {{ $json.url }}. Re-importing the workflow restores both.');
    }
    return JSON.parse(text.slice(start, end + 1));
  };

  // Makes an answer match the schema when the provider does not enforce it: missing keys get
  // an empty value, values outside an enum become "unknown"/null, wrong types are fixed.
  const conform = (value, schema) => {
    const types = [].concat(schema.type || []);
    const nullable = types.includes('null');
    if (schema.enum) {
      // Fall back to the value that claims the least: unknown, empty, or low confidence.
      if (schema.enum.includes(value)) return value;
      if (schema.enum.includes('unknown')) return 'unknown';
      if (nullable) return null;
      if (schema.enum.includes('low')) return 'low';
      return schema.enum[0];
    }
    if (types.includes('object')) {
      const src = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
      const out = {};
      for (const [k, sub] of Object.entries(schema.properties || {})) out[k] = conform(src[k], sub);
      return out;
    }
    if (types.includes('array')) {
      const arr = Array.isArray(value) ? value : [];
      const item = schema.items || {};
      // Drop list entries that are invalid instead of guessing a value for them
      // (an invalid road feature must not turn into "roundabout").
      const enumsOk = (v) => Object.entries(item.properties || {})
        .every(([k, s]) => !s.enum || s.enum.includes(v[k]));
      return arr
        .filter((v) => !item.enum || item.enum.includes(v))
        .filter((v) => !(item.type === 'object' && (!v || typeof v !== 'object' || !enumsOk(v))))
        .map((v) => conform(v, item));
    }
    if (types.includes('integer')) {
      const num = Math.round(Number(value));
      if (value !== null && value !== undefined && value !== '' && Number.isFinite(num)) return num;
      return nullable ? null : 0;
    }
    if (types.includes('boolean')) return value === true || value === 'true';
    if (types.includes('string')) {
      if (typeof value === 'string') return value;
      if (value === null || value === undefined) return nullable ? null : '';
      return String(value);
    }
    return value ?? null;
  };

  return { PROVIDERS, toRequests, contentOf, parse, conform };
})();

// ===== Choose the AI provider for each step here =====
// groq (free key) | gemini (free key) | openrouter (free models) | ollama (local, no key) | openai (paid)
// The key goes in the Header Auth credential of both LLM nodes:  Name: Authorization   Value: Bearer <key>
// (Ollama ignores the key, so one credential works when the two steps use different providers.)
const PROVIDER = {
  extraction: 'ollama',      // base qwen2.5:3b reads the story ('groq' here = better extraction, needs a key)
  reconstruction: 'ollama',  // the fine-tuned claimshield-recon (dev/finetune)
};

// Optional: other models than the defaults in dev/prompts/llm.js.
// Fine-tuned model: reconstruction: 'claimshield-recon' (the Ollama preset already uses it).
const MODEL_OVERRIDES = { extraction: null, reconstruction: null };

// Reconstruction prompt: 'v2' (few-shot, for general models) or 'ft1' (short prompt, for the
// fine-tuned model, which learned the format in training).
const RECONSTRUCTION_PROMPT = 'ft1'; // the prompt the fine-tuned model was trained with

// Reconstruction answers to compare (self-consistency). 3 is the design; 1 is faster and uses a
// third of the tokens, for quick tests on a free tier or a slow CPU.
const RECONSTRUCTION_SAMPLES = 3;

// Seconds between LLM calls. null = the provider's default (Groq 25 s, Gemini 7 s, Ollama/OpenAI 0).
// If you still get "too many requests" (429), raise it; with a paid key, set 0.
const CALL_INTERVAL_SECONDS = null;

const names = typeof PROVIDER === 'string' ? { extraction: PROVIDER, reconstruction: PROVIDER } : PROVIDER;
const provider = (role) => {
  const preset = LLM.PROVIDERS[names[role]];
  if (!preset) throw new Error(`Unknown provider "${names[role]}" for ${role}. Use one of: ${Object.keys(LLM.PROVIDERS).join(', ')}`);
  return {
    name: names[role],
    ...preset,
    models: { ...preset.models, [role]: MODEL_OVERRIDES[role] || preset.models[role] },
    callIntervalMs: CALL_INTERVAL_SECONDS === null ? preset.callIntervalMs : CALL_INTERVAL_SECONDS * 1000,
    samples: Math.max(1, Math.min(5, RECONSTRUCTION_SAMPLES)),
  };
};
const providers = { extraction: provider('extraction'), reconstruction: provider('reconstruction') };
if (!['v2', 'ft1'].includes(RECONSTRUCTION_PROMPT)) throw new Error('RECONSTRUCTION_PROMPT must be "v2" or "ft1"');

return [{
  json: {
    providers,
    reconstruction_prompt: `reconstruction-${RECONSTRUCTION_PROMPT}`,
    // Pause between the extraction call and the reconstruction calls: only needed when both go to
    // the same rate-limited provider.
    pause_seconds: providers.extraction.name === providers.reconstruction.name
      ? providers.reconstruction.callIntervalMs / 1000 : 0,
  },
}];

// Turns the geocoding result into the Overpass and Open-Meteo queries.
const n = $('Normalize input').first().json;
// Several searches ran ("Address variants"), most precise first; keep the first that found a place.
const place = $('Geocode incident').all().map((i) => i.json).find((p) => p && p.lat) || {}; // {} when nothing was found

const num = (v) => (Number.isFinite(Number.parseFloat(v)) ? Number.parseFloat(v) : null);
const lat = n.has_pin ? n.pin_lat : num(place.lat);
const lon = n.has_pin ? n.pin_lon : num(place.lon);
const hasLocation = lat !== null && lon !== null;
// place_rank >= 26 means street level or finer. A city-level match is too coarse
// to say whether a roundabout or traffic light is "there". A map pin is always precise.
const streetLevel = hasLocation && (n.has_pin || Number(place.place_rank) >= 26);

const R = 150; // metres around the incident point
const overpassQuery = `[out:json][timeout:20];(
way(around:${R},${lat},${lon})[highway];
node(around:${R},${lat},${lon})[highway~"^(traffic_signals|stop|give_way|mini_roundabout)$"];
nwr(around:${R},${lat},${lon})[amenity~"^(parking|fuel)$"];
);out tags;`;

// Public Overpass servers are often overloaded (502/504) or slow. The workflow tries them in
// this order, each with a short timeout, and continues without map checks if all fail.
const overpassUrls = [
  'https://overpass-api.de/api/interpreter',
  'https://overpass.private.coffee/api/interpreter',
  'https://maps.mail.ru/osm/tools/overpass/api/interpreter',
];

// The archive API lags about 5 days behind real time; recent incidents use the forecast API.
const base = n.days_ago > 5
  ? 'https://archive-api.open-meteo.com/v1/archive'
  : 'https://api.open-meteo.com/v1/forecast';
const weatherUrl = `${base}?latitude=${lat}&longitude=${lon}`
  + `&start_date=${n.incident_date}&end_date=${n.incident_date}`
  + '&hourly=temperature_2m,precipitation,rain,snowfall,weather_code'
  + '&daily=sunrise,sunset&timezone=auto';

return [{
  json: {
    has_location: hasLocation,
    street_level: streetLevel,
    location_source: n.has_pin ? 'map_pin' : hasLocation ? 'geocoded_address' : 'none',
    lat,
    lon,
    display_name: place.display_name || null,
    place_rank: place.place_rank ?? null,
    overpass_query: overpassQuery,
    overpass_urls: overpassUrls,
    weather_url: weatherUrl,
  },
}];

// Summarises the map and weather data into facts the scoring step can check.
// Reached from both branches of "Location found?", so the API nodes may not have run.
const n = $('Normalize input').first().json;
const q = $('Build queries').first().json;
const safe = (name) => {
  try { return $(name).first().json; } catch (e) { return null; }
};
// The first Overpass server that answered with data (main server, then the two mirrors).
const OVERPASS_NODES = ['Road context (Overpass)', 'Road context (mirror 1)', 'Road context (mirror 2)'];
const answered = q.has_location
  ? OVERPASS_NODES.find((name) => { const j = safe(name); return j && Array.isArray(j.elements); })
  : undefined;
const osm = answered ? safe(answered) : null;
const wx = q.has_location ? safe('Weather (Open-Meteo)') : null;

// ---- Road type, speed limit and nearby features (OpenStreetMap) ----
// Typical limits used when a road has no maxspeed tag.
const SPEED_DEFAULTS = {
  motorway: 120, trunk: 100, primary: 90, secondary: 80, tertiary: 70, unclassified: 60,
  residential: 50, living_street: 20, service: 30,
  motorway_link: 80, trunk_link: 70, primary_link: 60, secondary_link: 60,
};
const elements = osm && Array.isArray(osm.elements) ? osm.elements : [];
const ways = elements.filter((e) => e.type === 'way' && e.tags && e.tags.highway);
const speeds = ways
  .map((w) => Number.parseInt(w.tags.maxspeed, 10) || SPEED_DEFAULTS[w.tags.highway])
  .filter(Boolean);
const speedTagged = ways.some((w) => Number.parseInt(w.tags.maxspeed, 10));

const features = new Set();
for (const e of elements) {
  const t = e.tags || {};
  if (t.junction === 'roundabout' || t.highway === 'mini_roundabout') features.add('roundabout');
  if (t.highway === 'traffic_signals') features.add('traffic_light');
  if (['traffic_signals', 'stop', 'give_way'].includes(t.highway)) features.add('intersection');
  if (t.amenity === 'parking' || (t.highway === 'service' && t.service === 'parking_aisle')) features.add('parking_lot');
  if (t.amenity === 'fuel') features.add('fuel_station');
  if (t.bridge && t.bridge !== 'no') features.add('bridge');
  if (t.tunnel && t.tunnel !== 'no') features.add('tunnel');
  if (['motorway', 'trunk', 'motorway_link', 'trunk_link'].includes(t.highway)) features.add('highway');
  if (['residential', 'living_street', 'unclassified', 'service'].includes(t.highway)) features.add('residential_street');
}
// Two differently named roads within the radius means there is a junction nearby.
if (new Set(ways.map((w) => w.tags.name).filter(Boolean)).size >= 2) features.add('intersection');

// ---- Weather around the incident time (Open-Meteo) ----
const WMO = (c) => {
  if (c === null || c === undefined) return null;
  if (c === 0) return 'clear';
  if (c <= 3) return 'cloudy';
  if (c === 45 || c === 48) return 'fog';
  if (c >= 51 && c <= 57) return 'drizzle';
  if (c >= 61 && c <= 67) return 'rain';
  if (c >= 71 && c <= 77) return 'snow';
  if (c >= 80 && c <= 82) return 'rain showers';
  if (c === 85 || c === 86) return 'snow showers';
  if (c === 95) return 'thunderstorm';
  if (c >= 96) return 'thunderstorm with hail';
  return `code ${c}`;
};

let weather = null;
let light = null;
if (wx && wx.hourly && Array.isArray(wx.hourly.time)) {
  const h = wx.hourly;
  const hourOf = (t) => Number(t.slice(11, 13));
  // From 3 hours before to 1 hour after: rain that just stopped still leaves the road wet.
  const idx = h.time
    .map((t, i) => ({ hr: hourOf(t), i }))
    .filter((o) => o.hr >= n.incident_hour - 3 && o.hr <= n.incident_hour + 1)
    .map((o) => o.i);
  const pick = (k) => idx.map((i) => (h[k] || [])[i]).filter((v) => v !== null && v !== undefined);
  const sum = (a) => a.reduce((s, v) => s + v, 0);
  const at = h.time.findIndex((t) => hourOf(t) === n.incident_hour);
  const temps = pick('temperature_2m');
  weather = {
    summary_at_incident: WMO((h.weather_code || [])[at]),
    temp_c_at_incident: (h.temperature_2m || [])[at] ?? null,
    min_temp_c_window: temps.length ? Math.min(...temps) : null,
    precipitation_mm_window: Number(sum(pick('precipitation')).toFixed(1)),
    snowfall_cm_window: Number(sum(pick('snowfall')).toFixed(1)),
    weather_codes_window: [...new Set(pick('weather_code'))],
  };
}
if (wx && wx.daily && wx.daily.sunrise && wx.daily.sunset) {
  const sr = wx.daily.sunrise[0];
  const ss = wx.daily.sunset[0];
  const toMin = (s) => Number(s.slice(11, 13)) * 60 + Number(s.slice(14, 16));
  light = { sunrise: sr.slice(11, 16), sunset: ss.slice(11, 16), sunrise_min: toMin(sr), sunset_min: toMin(ss) };
}

return [{
  json: {
    location: {
      found: q.has_location,
      street_level: q.street_level,
      source: q.location_source,
      display_name: q.display_name,
      lat: q.lat,
      lon: q.lon,
    },
    road: {
      types: [...new Set(ways.map((w) => w.tags.highway))],
      max_speed_kmh: speeds.length ? Math.max(...speeds) : null,
      speed_source: speedTagged ? 'osm_tag' : speeds.length ? 'road_type_default' : null,
      features: [...features],
      data_available: osm !== null,
      source: answered || null,
    },
    weather,
    light,
  },
}];

// Shared controlled vocabulary. The Visual Inspection and Invoice Parser agents must use the
// same part names, otherwise the invoice comparison cannot match parts.
const VOCAB = {
  PARTS: [
    'front_bumper', 'rear_bumper', 'hood', 'trunk_lid_tailgate', 'front_grille', 'radiator',
    'headlight_left', 'headlight_right', 'taillight_left', 'taillight_right',
    'fender_front_left', 'fender_front_right', 'quarter_panel_rear_left', 'quarter_panel_rear_right',
    'door_front_left', 'door_front_right', 'door_rear_left', 'door_rear_right',
    'mirror_left', 'mirror_right', 'windshield', 'rear_window', 'side_window',
    'roof', 'wheel_rim', 'tire', 'suspension', 'airbag', 'engine_component',
  ],
  SCENARIOS: [
    'rear_end_struck', 'rear_end_striking', 'side_impact', 'sideswipe', 'parking_scrape',
