  PLACE_FEATURE_MISSING: 10,
  SPEED_IMPLAUSIBLE: 10,
  WEATHER_OR_LIGHT_CONTRADICTION: 15,
  INTERNAL_CONTRADICTION: 10,
  INVOICE_PART_IMPLAUSIBLE: 5,
  INVOICE_PART_IMPLAUSIBLE_MAX: 15,
