  .filter(Boolean);
if (!samples.length) {
  throw new Error(`Incident Plausibility: no readable answer from "Reconstruct incident x3 (LLM)". ${answerErrors[0]
    || "The model did not return JSON. Try the provider's larger model in LLM settings."}`);
